@namespace Components

<div class="checkout-wizard">
    @switch (_step)
    {
        case Step.Shipping:
            <ShippingStep Shipping="_order.Shipping" OnNext="HandleShippingNext" />
            break;
        case Step.Payment:
            <PaymentStep Payment="_order.Payment"
                         OnBack="HandlePaymentBack"
                         OnPlaceOrder="HandlePlaceOrder" />
            break;
    }
</div>

@code {
    private enum Step { Shipping, Payment }

    [Parameter]
    public EventCallback<Order> OnOrderPlaced { get; set; }

    private readonly Order _order = new();
    private Step _step = Step.Shipping;

    private void HandleShippingNext()
    {
        _step = Step.Payment;
    }

    private void HandlePaymentBack()
    {
        _step = Step.Shipping;
    }

    private async Task HandlePlaceOrder()
    {
        await OnOrderPlaced.InvokeAsync(_order);
    }
}

@namespace Components
@implements IDisposable
@inject IAddressValidator AddressValidator

<fieldset disabled="@_isValidating">
    <h3>Shipping Information</h3>

    <label>
        Name
        <input @bind="Shipping.Name" />
    </label>

    <label>
        Address
        <input @bind="Shipping.Address" />
    </label>

    <label>
        City
        <input @bind="Shipping.City" />
    </label>

    <label>
        Zip Code
        <input @bind="Shipping.ZipCode" />
    </label>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <p class="validation-error">@_validationError</p>
    }
</fieldset>

<button disabled="@_isValidating" @onclick="HandleNext">
    @if (_isValidating)
    {
        <span class="spinner" aria-hidden="true"></span>
        @:Validating…
    }
    else
    {
        @:Next
    }
</button>

@code {
    [Parameter]
    public ShippingInfo Shipping { get; set; } = default!;

    [Parameter]
    public EventCallback OnNext { get; set; }

    private CancellationTokenSource? _cts;
    private bool _isValidating;
    private string? _validationError;

    private async Task HandleNext()
    {
        if (_isValidating)
            return;

        _validationError = null;

        // Cancel any previous in-flight validation.
        CancelPendingValidation();

        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _isValidating = true;

        try
        {
            var isValid = await AddressValidator.ValidateAddressAsync(
                Shipping.Address, Shipping.City, Shipping.ZipCode, token);

            token.ThrowIfCancellationRequested();

            if (isValid)
            {
                await OnNext.InvokeAsync();
            }
            else
            {
                _validationError = "The address could not be verified. Please check and try again.";
            }
        }
        catch (OperationCanceledException)
        {
            // Validation was cancelled (user navigated away or re-submitted). No-op.
        }
        finally
        {
            _isValidating = false;
        }
    }

    private void CancelPendingValidation()
    {
        if (_cts is not null)
        {
            _cts.Cancel();
            _cts.Dispose();
            _cts = null;
        }
    }

    public void Dispose()
    {
        CancelPendingValidation();
    }
}

